// using System.Collections; using System.Text; using UnityEngine; using UnityEngine.Networking;
// Always answers 202, whether or not the address has an account. One a minute per address.
IEnumerator RequestEmailCode()
{
    string json = "{\"gameId\":42,\"email\":\"player@example.com\"}";
    using (var req = new UnityWebRequest("https://splattervault.com/rest/player-auth/email/code", "POST"))
    {
        req.uploadHandler = new UploadHandlerRaw(Encoding.UTF8.GetBytes(json));
        req.SetRequestHeader("Content-Type", "application/json");
        req.downloadHandler = new DownloadHandlerBuffer();
        yield return req.SendWebRequest();
        if (req.responseCode < 200 || req.responseCode >= 300)
        {
            // Refusals are { "error": "<code>", "message": "<sentence>" }: key on error.
            Debug.LogWarning(req.responseCode + ": " + req.downloadHandler.text);
            yield break;
        }
        string answer = req.downloadHandler.text; // JSON: parse with JsonUtility or Newtonsoft
    }
}

// POST /player-auth/email/code with the Unity SDK 4.0 (preview). Game client code: no API key.
// using SplatterVault.Core; using SplatterVault.Players; players = new SvPlayers(42) (your game id), made once and kept.
SvCodeSent sent = await players.Auth.RequestEmailCodeAsync("player@example.com");
// sent.ResendAfterSeconds: when to offer "send again"; the code lasts sent.ExpiresInSeconds.

// POST /player-auth/email/code with the Unreal plugin 0.1 (preview). Game client code: no API key (Game Id 42 in Project Settings).
// Sv: USplatterVaultSubsystem::GetClientFor(this) (null until configured); capture Sv in continuations.
Sv->Auth().RequestEmailCode(TEXT("player@example.com")).Next([](const TSvResult<FSvCodeSent>& R)
{
    if (R.IsOk()) { /* ask for the code; R.GetValue().ResendAfterSeconds before "send again" */ }
    else { UE_LOG(LogTemp, Warning, TEXT("%s"), *R.GetError().ToString()); } // act on R.GetError().Code
});

